import android.os.StatFs;
import android.system.Os;
import android.system.StructStatVfs;
public final class StatFsSmoke {
 private static void check(boolean value,String message){if(!value)throw new AssertionError(message);}
 public static void main(String[] args)throws Exception {
  android.app.ActivityManager manager=android.app.ActivityManager.shirazForProcess("statfs-test");long cap=Runtime.getRuntime().maxMemory();int expectedMiB=(int)Math.max(1L,Math.min(Integer.MAX_VALUE,cap/(1024L*1024L)));check(manager.getMemoryClass()==expectedMiB&&manager.getLargeMemoryClass()==expectedMiB,"actual VM heap cap MiB");check(expectedMiB==Integer.parseInt(args[3]),"configured Xmx reflected");
  android.app.ActivityManager.MemoryInfo memory=new android.app.ActivityManager.MemoryInfo();manager.getMemoryInfo(memory);long expectedTotal=0;try(java.io.BufferedReader reader=new java.io.BufferedReader(new java.io.FileReader("/proc/meminfo"))){String line;while((line=reader.readLine())!=null)if(line.startsWith("MemTotal:")){expectedTotal=Long.parseLong(line.trim().split("\\s+")[1])*1024;break;}}check(memory.totalMem==expectedTotal&&memory.totalMem>0&&memory.availMem>=0&&memory.availMem<=memory.totalMem,"real Linux memory counters");check(memory.lowMemory==(memory.availMem<memory.threshold)&&memory.threshold>0,"memory pressure policy");check(android.os.Debug.getNativeHeapAllocatedSize()>0&&android.os.Debug.getNativeHeapSize()>0&&android.os.Debug.getNativeHeapFreeSize()>=0,"native allocator accounting");try{manager.getMemoryInfo(null);throw new AssertionError("null memory output accepted");}catch(NullPointerException expected){}
  java.lang.reflect.Method conversion=android.app.ActivityManager.class.getDeclaredMethod("memoryClass",long.class);conversion.setAccessible(true);check(((Integer)conversion.invoke(null,0L))==1&&((Integer)conversion.invoke(null,2097151L))==1&&((Integer)conversion.invoke(null,Long.MAX_VALUE))==Integer.MAX_VALUE,"heap MiB minimum/floor/overflow bounds");
  final int parentPriority=android.os.Process.getThreadPriority(android.os.Process.myTid());final java.util.concurrent.CountDownLatch delivered=new java.util.concurrent.CountDownLatch(1);final int[] observed={-99,-99};
  android.os.HandlerThread worker=new android.os.HandlerThread("capacity-background",10){protected void onLooperPrepared(){observed[0]=android.os.Process.getThreadPriority(android.os.Process.myTid());}};worker.start();android.os.Handler handler=new android.os.Handler(worker.getLooper());handler.post(new Runnable(){public void run(){observed[1]=android.os.Process.getThreadPriority(android.os.Process.myTid());delivered.countDown();}});check(delivered.await(5,java.util.concurrent.TimeUnit.SECONDS)&&observed[0]==10&&observed[1]==10,"real worker nice before callback/dispatch");check(android.os.Process.getThreadPriority(android.os.Process.myTid())==parentPriority,"parent nice unchanged");worker.quitSafely();worker.join(5000);check(!worker.isAlive()&&worker.getThreadId()==-1&&worker.getLooper()==null,"worker shutdown");
  final Throwable[] failure={null};android.os.HandlerThread invalidWorker=new android.os.HandlerThread("invalid-priority",20);invalidWorker.setUncaughtExceptionHandler(new Thread.UncaughtExceptionHandler(){public void uncaughtException(Thread thread,Throwable error){failure[0]=error;}});invalidWorker.start();invalidWorker.getLooper();invalidWorker.join(5000);check(!invalidWorker.isAlive()&&invalidWorker.getLooper()==null&&invalidWorker.getThreadId()==-1&&failure[0] instanceof IllegalArgumentException,"priority failure cleanup and waiter release");
  String path=args[0];StatFs stat=new StatFs(path);check(stat.getBlockSizeLong()==Long.parseLong(args[1])&&stat.getBlockCountLong()==Long.parseLong(args[2]),"Python host fragment size/count");
  check(stat.getFreeBlocksLong()>=stat.getAvailableBlocksLong()&&stat.getAvailableBlocksLong()>=0,"free versus available");
  check(stat.getFreeBytes()==stat.getFreeBlocksLong()*stat.getBlockSizeLong()&&stat.getAvailableBytes()==stat.getAvailableBlocksLong()*stat.getBlockSizeLong()&&stat.getTotalBytes()==stat.getBlockCountLong()*stat.getBlockSizeLong(),"byte products");
  long before=stat.getAvailableBlocksLong();for(String invalid:new String[]{path+"/missing",path+"\u0000/suffix",""}){try{stat.restat(invalid);throw new AssertionError("invalid path accepted");}catch(IllegalArgumentException expected){check(stat.getAvailableBlocksLong()==before,"failed restat atomicity");}}
  try{new StatFs(null);throw new AssertionError("null accepted");}catch(NullPointerException expected){}
  stat.restat("/proc");StructStatVfs proc=Os.statvfs("/proc");check(stat.getBlockSizeLong()==proc.f_frsize&&stat.getBlockCountLong()==proc.f_blocks,"restat different filesystem");
  // Controlled snapshot tests exercise legacy narrowing and free/available distinction
  // independently of whether this host filesystem exceeds signed int block counts.
  java.lang.reflect.Field field=StatFs.class.getDeclaredField("mStat");field.setAccessible(true);field.set(stat,new StructStatVfs(8192,4096,0x100000003L,0x80000005L,0x80000001L,0,0,0,0,0,255));
  check(stat.getBlockSize()==4096&&stat.getBlockSizeLong()==4096,"fragment size not preferred IO size");check(stat.getBlockCount()==3&&stat.getBlockCountLong()==0x100000003L,"legacy count cast");check(stat.getFreeBlocks()==(int)0x80000005L&&stat.getAvailableBlocks()==(int)0x80000001L,"legacy free/available casts");check(stat.getFreeBytes()-stat.getAvailableBytes()==16384,"reserved blocks preserved");
  stat.restat(path);check(stat.getBlockCountLong()==Long.parseLong(args[2]),"snapshot replaced by real restat");System.out.println("STATFS_HOST_SNAPSHOT_OK");
 }
}
